cuts2fit200=struct('cuts_list',[]);
cuts2fit200.mask_ds1 = cell(2,1);
cuts2fit200.mask_ds2 = cell(2,1);
cuts2fit200.mask_ds3 = cell(2,1);

fit_cuts_file = 'multicuts_fit_dataGH_ei200meV'

function [masked_data,varargout] = mask_cut(cut_data,varargin)
masked_data = cut_data;
for i=1:numel(varargin)
    mask_vert = varargin{i};
    if isempty(mask_vert)
        fh=plot(masked_data);liny; lz 0 2;    
        [ms,~,mask_vert] = draw_mask(fh);
    else
        ms = draw_mask(masked_data,'mask',mask_vert);    
    end
    masked_data = mask(masked_data,ms);    
    varargout{i} = mask_vert';
    plot(masked_data);liny; lz 0 0.5; keep_figure;
end
end

[w2_400mfit,msk400m_vert1,msk400m_vert2] = mask_cut(w2_400mfit,cuts2fit400.mask_ds1{:})
cuts2fit400.mask_ds1 = {msk400m_vert1,msk400m_vert2};
[w2_400afit,msk400a_vert1,msk400a_vert2]= mask_cut(w2_400afit,cuts2fit400.mask_ds2{:})
cuts2fit400.mask_ds2 = {msk400a_vert1,msk400a_vert2};
[w2_400bfit,msk400b_vert1,msk400b_vert2] = mask_cut(w2_400bfit,cuts2fit400.mask_ds3{:})
cuts2fit400.mask_ds3 = {msk400b_vert1,msk400b_vert2};
cuts2fit400.cuts_list = {w2_400mfit,w2_400afit,w2_400bfit};

save(fit_cuts_file,'cuts2fit400')
